def solve(inputs: dict) -> float:
    import re
    residues = None
    moduli = None
    # try direct keys
    for k, v in inputs.items():
        if isinstance(v, (list, tuple)):
            if residues is None:
                residues = list(v)
            else:
                moduli = list(v)
    if residues is None or moduli is None:
        # parse two bracketed lists from text
        text = " ".join(str(v) for v in inputs.values())
        lists = re.findall(r'\[([^\]]*)\]', text)
        if len(lists) >= 2:
            residues = [int(x) for x in re.findall(r'-?\d+', lists[0])]
            moduli = [int(x) for x in re.findall(r'-?\d+', lists[1])]
    # CRT
    from functools import reduce
    M = 1
    for m in moduli:
        M *= int(m)
    x = 0
    for a, m in zip(residues, moduli):
        a = int(a); m = int(m)
        Mi = M // m
        # inverse of Mi mod m
        inv = pow(Mi, -1, m)
        x += a * Mi * inv
    return float(x % M)

